\label{kesten}
	Let a group $G$ act on a countable set $X$ and let $\mu$ be a measure on $G$. The following are equivalent:
	
	\begin{enumerate}
		\item The action of $G$ on $X$ is amenable.
		\item The Markov operator corresponding to the random walk defined by $\mu$ has norm $||P||=1$.  
		\item The inverse spectral radius $\rho (X, \mu)$ of the random walk is equal to 1.
	\end{enumerate}

\label{north-equiv}
	Let $\beta: \mathbb{N} \rightarrow \mathbb{R}_{>0}$ be a non-increasing function satisfying $\lim\limits_{n \rightarrow \infty} \beta(n) = 0$.
	The action of $G$ on $X$ is amenable if and only if for any positive superharmonic function $f$ with respect to $\mu$ there exists a sequence $\{E_n\}$ such that any word $g$ of length not exceeding $n$ satisfies $\left|\frac{f(gE_n)}{f(E_n)}-1\right| < \beta(n)$.

Let $\varphi$ be a function defined on a set $X$ and achieving its maximum at the root point $p$. Then the function $f : \mathcal{P}_f(X) \rightarrow \mathbb{R} $ defined by 
		\begin{itemize}
			\item $f(E) = \min\limits_{x \in E} \varphi(x)$ 
			\item $f (\varnothing) = \varphi (p)$
		\end{itemize}
		
		is called the min-function of $\varphi$.

Define 
	\begin{itemize}
		\item $T_1f(E)=\frac{1}{4} (f(aE)+f(bE)+f(a^{-1}E)+f(b^{-1}E))$
		\item $T_2f(E)=f(E \Delta p)$
		\item $Tf(E)=\alpha T_1f(E)+(1-\alpha) T_2f(E)$, $\alpha \in (0,1)$.
	\end{itemize}
	
	
	Let $E$ be a non-empty finite subset of $X$ and let $x$ be the point in $E$ minimizing $\varphi$. Then by definition:
	
	$f(aE) \le \varphi(a.x)$;
	
	$f(bE) \le \varphi(b.x)$;
	
	$f(a^{-1}E) \le \varphi(a^{-1}.x)$;
	
	$f(b^{-1}E) \le \varphi(b^{-1}.x)$;
	
	$T_1f(E)=\frac{1}{4}(f(aE)+f(bE)+f(a^{-1}E)+f(b^{-1}E)) \le \frac{1}{4}(\varphi(a.x)+\varphi(b.x)+\varphi(a^{-1}.x)+ \varphi(b^{-1}.x)) =P\varphi(x) \le \varphi(x) = f(E)$
	
	$T_2f(E) = f(E)$ since by definition $\varphi(p) \ge \varphi(x)$.
	
	Hence, $Tf(E) \le f(E)$ for any non-empty $E$. For the empty set the statement is easily checked by hand.

\label{not-supharm}
	Let $\varphi$ be a function on $X$ such that:
	\begin{itemize}
		\item $\varphi$ is not superharmonic;
		\item $\varphi(x) \le \varphi(p)$ for any $x \in X$.
	\end{itemize}
	
	Then the corresponding min-function $f$ is not superharmonic either.

\label{first}
	Let $X$ be the Schreier graph of Thompson's group $F$ with $p$ being the root vertex. Let $\varphi$ be a positive superharmonic (with respect to the uniform measure) function on $X$ such that $f(q) \le f(p)$ for all points $q \in X$ and $f$ be its min-function.
	
	Then there is a sequence $E_n \in \mathcal{P}_f(X)$, $n \in \mathbb{N}$, such that for any $g \in \mathcal{P}_f(X) \rtimes F$ the sequence $\frac{f(gE_n)}{f(E_n)}$ converges to 1.

\label{sigen}
	Let $f_i$, $i=\overline{1,k}$, be the min-functions obtained from $\varphi_i$ (not necessarily distinct. Let $s_i$ and $\lambda_i>0$, $i=\overline{1,k}$, be fixed elements of $G$
	and real numbers respectively. Then there is a sequence $\{E_n\}$ such that for any word $g \in \mathcal{P}_f(X) \rtimes F$:  \[\frac{\sum\limits_{1 \le i \le k} \lambda_i f_i (s_igE_n) }{ \sum\limits_{1 \le i \le k} \lambda_i f_i (s_i E_n)} \rightarrow 1, \ n \rightarrow \infty.\]

First we show that for each $n \ge 4$ there is a finite set $E_n$ such that for each $i=\overline{1,k}$ and for any word $g$ of length $\le n$ the following two estimates hold:
	
	\begin{itemize}
		\item $\left| \frac{f_i(s_igE_n)}{f(E_n)}-1 \right| < \frac{1}{n}$;
		\item $\left| \frac{f_i(s_iE_n)}{f(E_n)}-1\right| < \frac{1}{n}$.
	\end{itemize}
	
	This holds because according to the proof of Theorem \ref{second}, there exists a finite set $E$ such that for all elements $g$ such that $|g|\le m = n+\max\limits_{i=\overline{1,k}} |s_i|$ and for all $i=\overline{1,k}$ we have that $|\frac{f_i(gE)}{f_i(E)} -1| < \frac{1}{m} < \frac{1}{n}$. Since the lengths of $s_ig$ and $s_i$ do not exceed $m$, both inequalities are true for $E_n:=E$. Thus, for any $g$ and all $i=\overline{1,k}$:
	
	\[ \frac{f_i(s_igE_n)}{f_i(s_iE_n)} = \frac{f_i(s_igE_n)/f_i(E_n)}{f_i(s_iE_n)/f_i(E_n)} \rightarrow \frac{1}{1} = 1. \]
	
	Fix $\varepsilon > 0$. From the convergence above, there is a number $N \in \mathbb{N}$ such that for all $n \ge N$: 	\[ f_i(s_igE_n) \in \left((1-\varepsilon){f_i(s_iE_n)} , (1+\varepsilon){f_i(s_iE_n)}\right). \] Summing up the inequalities above with corresponding weights, we get \[ \sum\limits_{1 \le i \le k} \lambda_i f_i (s_igE_n) \in \left((1-\varepsilon)\sum\limits_{1 \le i \le k} \lambda_i f_i (s_i E_n) , (1+\varepsilon)\sum\limits_{1 \le i \le k} \lambda_i f_i (s_i E_n)\right), \] which implies \[ \frac{\sum\limits_{1 \le i \le k} \lambda_i f_i (s_igE_n)}{\sum\limits_{1 \le i \le k}\lambda_i f_i (s_i E_n)} \in (1-\varepsilon, 1+\varepsilon). \] The latter is equivalent to convergence to 1.

Let $X$ be the Schreier graph of Thompson's group $F$ with $p$ being the root vertex. Let $\varphi$ be a positive superharmonic function on $X$ such that $\varphi(q) \le \varphi(p) $ for any $q \in X$ and $\inf\limits_{x \in X} \varphi (x) = 0$. As before, define the min-function $f : \mathcal{P}_f(X) \rightarrow \mathbb{R} $ by 
		\begin{itemize}
			\item $f(E) = \min\limits_{x \in E} \varphi(x), \ E \neq \varnothing$ 
			\item $f (\varnothing) = \varphi (p)$.
		\end{itemize}
		
		
		Then $f$ is a potential.
